			{
				if (y > GenVars.remixSurfaceLayerLow)
				{
					return y < GenVars.remixSurfaceLayerHigh;
				}
				return false;
			}
			if (GenVars.worldSpawnHasBeenRandomized || !Main.isThereAWorldSurface)
			{
				if ((double)y > Main.worldSurface)
				{
					return y < Main.UnderworldLayer;
