			List<Point> list2 = new List<Point>();
			HashSet<Point> hashSet = new HashSet<Point>();
			list2.Add(new Point(x, y));
			while (list2.Count > 0)
			{
				list.Clear();
				list.AddRange(list2);
				list2.Clear();
				while (list.Count > 0)
				{
					Point item = list[0];
					if (!InWorld(item.X, item.Y, 1))
					{
						list.Remove(item);
						continue;
					}
					hashSet.Add(item);
					list.Remove(item);
					Tile tile = Main.tile[item.X, item.Y];
					if (SolidTile(item.X, item.Y) || tile.wall != 0)
					{
						if (tile.active() && tile.wall == 0)
						{
							tile.wall = wall;
						}
						continue;
					}
					tile.wall = wall;
					Point item2 = new Point(item.X - 1, item.Y);
					if (!hashSet.Contains(item2))
					{
						list2.Add(item2);
					}
					item2 = new Point(item.X + 1, item.Y);
					if (!hashSet.Contains(item2))
					{
						list2.Add(item2);
					}
					item2 = new Point(item.X, item.Y - 1);
					if (!hashSet.Contains(item2))
					{
						list2.Add(item2);
					}
					item2 = new Point(item.X, item.Y + 1);
					if (!hashSet.Contains(item2))
					{
						list2.Add(item2);
