		public static void Wall2(int x, int y, int wallType)
{
		using (new global::Terraria.CallTracker("Terraria.WorldGen.Spread.Wall2"))
		{
			if (!InWorld(x, y))
			{
				return;
			}
			ushort num = (ushort)wallType;
			int num2 = 0;
			int maxWallOut = maxWallOut2;
			List<Point> list = new List<Point>();
			List<Point> list2 = new List<Point>();
			HashSet<Point> hashSet = new HashSet<Point>();
			list2.Add(new Point(x, y));
			while (list2.Count > 0)
			{
				list.Clear();
				list.AddRange(list2);
				list2.Clear();
				while (list.Count > 0)
				{
					Point item = list[0];
					if (!InWorld(item.X, item.Y, 1))
					{
						list.Remove(item);
						continue;
					}
					hashSet.Add(item);
					list.Remove(item);
					Tile tile = Main.tile[item.X, item.Y];
					if (tile.wall == num || WallID.Sets.CannotBeReplacedByWallSpread[tile.wall])
					{
						continue;
					}
					if (!SolidTile(item.X, item.Y))
					{
						bool flag = WallID.Sets.WallSpreadStopsAtAir[num];
						if (flag && tile.wall == 0)
						{
							list.Remove(item);
							continue;
						}
						num2++;
						if (num2 >= maxWallOut)
						{
							list.Remove(item);
							continue;
						}
						tile.wall = num;
						Point item2 = new Point(item.X - 1, item.Y);
						if (!hashSet.Contains(item2))
						{
							list2.Add(item2);
						}
						item2 = new Point(item.X + 1, item.Y);
						if (!hashSet.Contains(item2))
						{
							list2.Add(item2);
						}
						item2 = new Point(item.X, item.Y - 1);
						if (!hashSet.Contains(item2))
						{
							list2.Add(item2);
						}
						item2 = new Point(item.X, item.Y + 1);
						if (!hashSet.Contains(item2))
						{
							list2.Add(item2);
						}
						if (flag)
						{
							item2 = new Point(item.X - 1, item.Y - 1);
							if (!hashSet.Contains(item2))
							{
								list2.Add(item2);
							}
							item2 = new Point(item.X + 1, item.Y - 1);
							if (!hashSet.Contains(item2))
							{
								list2.Add(item2);
							}
							item2 = new Point(item.X - 1, item.Y + 1);
							if (!hashSet.Contains(item2))
							{
								list2.Add(item2);
							}
							item2 = new Point(item.X + 1, item.Y + 1);
							if (!hashSet.Contains(item2))
							{
								list2.Add(item2);
							}
							item2 = new Point(item.X - 2, item.Y);
							if (!hashSet.Contains(item2))
							{
								list2.Add(item2);
							}
							item2 = new Point(item.X + 2, item.Y);
							if (!hashSet.Contains(item2))
							{
								list2.Add(item2);
							}
						}
					}
					else if (tile.active())
					{
						tile.wall = num;
					}
				}
			}
		}
		}
