				{
					Point item = list[0];
					if (!InWorld(item.X, item.Y, 1))
					{
						list.Remove(item);
						continue;
					}
					hashSet.Add(item);
					list.Remove(item);
					Tile tile = Main.tile[item.X, item.Y];
					if (SolidTile(item.X, item.Y) || tile.wall != 0)
					{
						if (tile.active())
						{
							if (Gemmable(tile.type))
							{
								tile.type = randGemTile();
							}
							Tile tile2 = Main.tile[item.X - 1, item.Y];
