		{
			feedback = NoRoomCheckFeedback.WithText;
		}
		sharedRoomX = -1;
		if (ScoreRoom_IsThisRoomOccupiedBySomeone(ignoreNPC, npcTypeAskingToScoreRoom))
		{
			hiScore = -1;
