	public static bool CanGeneratePressurePlateAt(int i, int j)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.CanGeneratePressurePlateAt"))
	{
		if (!InWorld(i, j, 3))
		{
			return false;
		}
		if (!SolidTileAllowBottomSlope(i, j + 1))
		{
			return false;
		}
		Tile tile = Main.tile[i, j + 1];
		if (tile.type >= 0 && TileID.Sets.Boulders[tile.type])
		{
			return false;
		}
		if (tile.wall == 350)
		{
			return false;
		}
		return true;
	}
