						if (num3 >= Main.maxTilesX * 2)
						{
							flag4 = false;
						}
						flag = !(flag2 || flag3 || flag4);
					}
					dunesBiome.Place(origin, GenVars.structures);
					if (genRand.NextDouble() <= num)
