	public static bool DefaultTreeWallTest(int wallType)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.DefaultTreeWallTest"))
	{
		if (wallType >= 0 && wallType < WallID.Count && WallID.Sets.AllowsPlantsToGrow[wallType])
		{
			return true;
		}
		return false;
	}
	}
	public static bool GemTreeWallTest(int wallType)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.GemTreeWallTest"))
	{
		if (DefaultTreeWallTest(wallType))
		{
			return true;
		}
		switch (wallType)
		{
		case 2:
		case 54:
		case 55:
