		case 212:
		case 213:
		case 214:
		case 215:
			return true;
		default:
			return false;
		}
	}
	}
	public static bool GemTreeGroundTest(int tileType)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.GemTreeGroundTest"))
