		{
			num4 -= 54;
			num5++;
		}
		if (frameX >= 72)
		{
			num5 += 36 * (frameX / 72);
			num6 += 54 * (frameX / 72);
		}
		num3 = j - num4 / 18;
		switch (frameX % 72)
		{
		case 0:
			num2 = i;
			num = 1;
			break;
		case 18:
			num2 = i - 1;
			num = 1;
			break;
		case 36:
			num2 = i + 1;
			num = -1;
			break;
		case 54:
			num2 = i;
			num = -1;
			break;
		}
		int num7 = num2;
