	public static bool UpdateStalagtiteStyle(int x, int j)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.UpdateStalagtiteStyle"))
	{
		if (Main.tile[x, j] == null)
		{
			return true;
		}
		GetStalagtiteStyle(x, j, out var style, out var fail);
		if (fail)
		{
			return false;
		}
		GetDesiredStalagtiteStyle(x, j, out var fail2, out var desiredStyle, out var height, out var y);
		if (fail2)
		{
			return false;
		}
		if (style != desiredStyle)
		{
			int num = genRand.Next(3) * 18;
			switch (desiredStyle)
			{
			case 0:
				num += 54;
				break;
			case 1:
				num += 216;
				break;
			case 2:
				num += 270;
				break;
			case 3:
				num += 324;
				break;
			case 4:
				num += 378;
				break;
			case 5:
				num += 432;
				break;
			case 6:
				num += 486;
				break;
			case 7:
				num = num;
				break;
			case 8:
				num += 540;
				break;
			case 9:
				num += 594;
				break;
			case 10:
				num += 648;
				break;
			case 11:
				num += 108;
				break;
			case 12:
				num += 162;
				break;
			}
			for (int i = y; i < y + height; i++)
			{
				Main.tile[x, i].frameX = (short)num;
			}
				NetMessage.SendTileSquare(-1, x, y, 1, 2);
		}
		return true;
	}
	}
