		if (tile3 == null)
		{
			return;
		}
		bool num = tile2.active() && tile2.type == 571;
		bool flag = tile.active() && tile.type == 571;
		int num2 = tile3.frameX / 18;
		tile3.frameY = 0;
		if (num)
		{
			if (flag)
			{
