		{
			return false;
		}
		if (Main.tile[x, y].active() && (Main.tileCut[Main.tile[x, y].type] || TileID.Sets.BreakableWhenPlacing[Main.tile[x, y].type] || TileID.Sets.IsADripTile[Main.tile[x, y].type]))
		{
