			}
			switch (type)
			{
			case 323:
				if (tile.type != type && (tile2.frameX == 66 || tile2.frameX == 220))
				{
					return false;
				}
				break;
			case 21:
			case 26:
			case 72:
			case 77:
			case 88:
			case 467:
			case 488:
				if (tile.type != type)
				{
					return false;
				}
				break;
			case 80:
				if (tile.type != type)
				{
					int num = tile2.frameX / 18;
					if ((uint)num <= 1u || (uint)(num - 4) <= 1u)
					{
