					}
				}
				break;
			}
		}
		if (TileID.Sets.Boulders[tile.type] && CheckBoulderChest(i, j))
		{
			blockDamaged = true;
			return false;
		}
		switch (tile.type)
		{
		case 10:
			if (IsLockedDoor(tile))
			{
				blockDamaged = true;
				return false;
			}
			break;
		case 235:
