	public static bool IsOpenDoorAnchorFrame(int x, int y)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.IsOpenDoorAnchorFrame"))
	{
		Tile tile = Main.tile[x, y];
		if (!tile.active() || tile.type != 11)
		{
			return false;
		}
		int num = tile.frameX % 72;
		if (num >= 18)
		{
			return num >= 54;
		}
		return true;
	}
	}
	public static bool IsLockedDoor(Tile t)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.IsLockedDoor"))
	{
		if (t.type == 10 && t.frameY >= 594 && t.frameY <= 646)
		{
			return t.frameX < 54;
		}
		return false;
	}
	}
