	public static int CountNearBlocksTypes(int i, int j, int radius, int cap = 0, params int[] tiletypes)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.CountNearBlocksTypes"))
	{
		if (tiletypes.Length == 0)
		{
			return 0;
		}
		int value = i - radius;
		int value2 = i + radius;
		int value3 = j - radius;
		int value4 = j + radius;
		int num = Utils.Clamp(value, 0, Main.maxTilesX - 1);
		value2 = Utils.Clamp(value2, 0, Main.maxTilesX - 1);
		value3 = Utils.Clamp(value3, 0, Main.maxTilesY - 1);
		value4 = Utils.Clamp(value4, 0, Main.maxTilesY - 1);
		int num2 = 0;
		for (int k = num; k <= value2; k++)
		{
			for (int l = value3; l <= value4; l++)
			{
				if (!Main.tile[k, l].active())
				{
					continue;
				}
				for (int m = 0; m < tiletypes.Length; m++)
				{
					if (tiletypes[m] == Main.tile[k, l].type)
					{
						num2++;
						if (cap <= 0 || num2 < cap)
						{
							break;
						}
						return num2;
					}
				}
			}
		}
		return num2;
	}
	}
