	public static void SquareTileFrame(int i, int j, bool resetFrame = true)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.SquareTileFrame"))
	{
		TileFrame(i - 1, j - 1);
		TileFrame(i - 1, j);
		TileFrame(i - 1, j + 1);
		TileFrame(i, j - 1);
		TileFrame(i, j, resetFrame);
		TileFrame(i, j + 1);
		TileFrame(i + 1, j - 1);
		TileFrame(i + 1, j);
		TileFrame(i + 1, j + 1);
	}
	}
	public static void SquareWallFrame(int i, int j, bool resetFrame = true)
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.SquareWallFrame"))
	{
		Framing.WallFrame(i - 1, j - 1);
		Framing.WallFrame(i - 1, j);
		Framing.WallFrame(i - 1, j + 1);
		Framing.WallFrame(i, j - 1);
		Framing.WallFrame(i, j, resetFrame);
		Framing.WallFrame(i, j + 1);
		Framing.WallFrame(i + 1, j - 1);
		Framing.WallFrame(i + 1, j);
		Framing.WallFrame(i + 1, j + 1);
	}
