	public static void UpdateLunarApocalypse()
{
	using (new global::Terraria.CallTracker("Terraria.WorldGen.UpdateLunarApocalypse"))
	{
		if (!NPC.LunarApocalypseIsUp)
		{
			return;
		}
		bool flag = false;
		bool flag2 = false;
		bool flag3 = false;
		bool flag4 = false;
		bool flag5 = false;
		for (int i = 0; i < Main.maxNPCs; i++)
		{
			if (Main.npc[i].active)
			{
				switch (Main.npc[i].type)
				{
				case 398:
					flag = true;
					break;
				case 517:
					flag2 = true;
					break;
				case 422:
					flag3 = true;
					break;
				case 507:
					flag4 = true;
					break;
				case 493:
					flag5 = true;
					break;
				}
			}
		}
		if (!flag2)
		{
			NPC.TowerActiveSolar = false;
		}
		if (!flag3)
		{
			NPC.TowerActiveVortex = false;
		}
		if (!flag4)
		{
			NPC.TowerActiveNebula = false;
		}
		if (!flag5)
		{
			NPC.TowerActiveStardust = false;
		}
		if (!NPC.TowerActiveSolar && !NPC.TowerActiveVortex && !NPC.TowerActiveNebula && !NPC.TowerActiveStardust && !flag)
		{
			StartImpendingDoom(3600);
		}
	}
	}
